-- V004: Agregar CHECK Constraints y UNIQUE para mejorar integridad

-- Para SQLite, necesitamos recrear tablas para agregar CHECKs
-- SQLite no permite ALTER TABLE ADD CONSTRAINT

-- ============================================================
-- 1. TABLA MARCADORES: Agregar CHECK en url_estado y UNIQUE en url
-- ============================================================
BEGIN TRANSACTION;

CREATE TABLE Marcadores_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    titulo TEXT NOT NULL,
    url TEXT NOT NULL,
    descripcion TEXT,
    portada BLOB,
    categoria_id INTEGER,
    usuario_id INTEGER NOT NULL,
    fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,
    ultima_apertura DATETIME,
    github_stars INTEGER DEFAULT 0,
    github_forks INTEGER DEFAULT 0,
    github_watchers INTEGER DEFAULT 0,
    github_languages TEXT,
    url_estado TEXT DEFAULT 'desconocido',
    ultima_verificacion DATETIME,
    FOREIGN KEY (categoria_id) REFERENCES Categorias(id) ON DELETE CASCADE,
    FOREIGN KEY (usuario_id) REFERENCES Usuarios(id) ON DELETE CASCADE,
    CHECK (url_estado IN ('activo', 'inactivo', 'error', 'desconocido')),
    UNIQUE (url, usuario_id)
);

INSERT INTO Marcadores_v2 SELECT * FROM Marcadores;
DROP TABLE Marcadores;
ALTER TABLE Marcadores_v2 RENAME TO Marcadores;

COMMIT;

-- ============================================================
-- 2. TABLA CATEGORIAS: Agregar UNIQUE en (nombre, usuario_id)
-- ============================================================
BEGIN TRANSACTION;

CREATE TABLE Categorias_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL,
    padre_id INTEGER,
    usuario_id INTEGER NOT NULL,
    fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (padre_id) REFERENCES Categorias(id) ON DELETE CASCADE,
    FOREIGN KEY (usuario_id) REFERENCES Usuarios(id) ON DELETE CASCADE,
    CHECK (LENGTH(TRIM(nombre)) > 0),
    UNIQUE (nombre, usuario_id)
);

INSERT INTO Categorias_v2 SELECT * FROM Categorias;
DROP TABLE Categorias;
ALTER TABLE Categorias_v2 RENAME TO Categorias;

COMMIT;

-- ============================================================
-- 3. TABLA USUARIOS: Agregar CHECK en email y username
-- ============================================================
BEGIN TRANSACTION;

CREATE TABLE Usuarios_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    username TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,
    CHECK (email LIKE '%@%'),
    CHECK (LENGTH(username) >= 3)
);

INSERT INTO Usuarios_v2 SELECT * FROM Usuarios;
DROP TABLE Usuarios;
ALTER TABLE Usuarios_v2 RENAME TO Usuarios;

COMMIT;

-- ============================================================
-- 4. TABLA TAGS: Agregar CHECK en nombre
-- ============================================================
BEGIN TRANSACTION;

CREATE TABLE Tags_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL,
    color TEXT NOT NULL,
    usuario_id INTEGER NOT NULL,
    fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,
    es_default BOOLEAN DEFAULT 0,
    FOREIGN KEY (usuario_id) REFERENCES Usuarios(id) ON DELETE CASCADE,
    UNIQUE (nombre, usuario_id),
    CHECK (LENGTH(TRIM(nombre)) > 0)
);

INSERT INTO Tags_v2 SELECT * FROM Tags;
DROP TABLE Tags;
ALTER TABLE Tags_v2 RENAME TO Tags;

COMMIT;

-- ============================================================
-- 5. TABLA verification_log: Agregar CHECK en status
-- ============================================================
BEGIN TRANSACTION;

CREATE TABLE verification_log_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    last_verification DATETIME DEFAULT CURRENT_TIMESTAMP,
    status TEXT DEFAULT 'completed',
    marcadores_verificados INTEGER DEFAULT 0,
    marcadores_invalidos INTEGER DEFAULT 0,
    errores TEXT,
    CHECK (status IN ('completed', 'pending', 'error'))
);

INSERT INTO verification_log_v2 SELECT * FROM verification_log;
DROP TABLE verification_log;
ALTER TABLE verification_log_v2 RENAME TO verification_log;

COMMIT;

describe('Autenticación', () => {
  describe('Validaciones de contraseña', () => {
    it('debería rechazar contraseñas vacías', () => {
      const password = '';
      expect(password.length).toBeLessThan(6);
    });

    it('debería validar contraseñas con caracteres especiales', () => {
      const password = 'Pass123!@#';
      expect(password.length).toBeGreaterThanOrEqual(6);
      expect(/[0-9]/.test(password)).toBe(true);
    });

    it('debería rechazar contraseñas menores a 6 caracteres', () => {
      const password = '12345';
      expect(password.length < 6).toBe(true);
    });

    it('debería acepar contraseñas válidas', () => {
      const password = 'ValidPassword123';
      expect(password.length >= 6).toBe(true);
    });
  });

  describe('Validaciones de email', () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    it('debería validar emails correctos', () => {
      expect(emailRegex.test('usuario@example.com')).toBe(true);
    });

    it('debería rechazar emails sin arroba', () => {
      expect(emailRegex.test('usuarioexample.com')).toBe(false);
    });

    it('debería rechazar emails sin dominio', () => {
      expect(emailRegex.test('usuario@')).toBe(false);
    });

    it('debería rechazar emails vacíos', () => {
      expect(emailRegex.test('')).toBe(false);
    });
  });
});

