import React, { useState, useEffect } from 'react';
import TagBadge from './TagBadge';
import TagPopover from './TagPopover';
import { bookmarksService } from '../services/bookmarksService';
import { tagsService } from '../services/tagsService';
import { categoriesService } from '../services/categoriesService';
import { useToast } from '../hooks/useToast';
import './CreateBookmarkModal.css';

function CreateBookmarkModal({ isOpen, onClose, onBookmarkCreated, defaultFolderId }) {
    const toast = useToast();
    const [isPopoverOpen, setIsPopoverOpen] = useState(false);
    const [selectedTagIds, setSelectedTagIds] = useState([]);
    const [tags, setTags] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [scrapingUrl, setScrapingUrl] = useState(null);
    const [scrapingToastId, setScrapingToastId] = useState(null);
    const [gitHubData, setGitHubData] = useState(null); // Almacena datos de GitHub

    const [formData, setFormData] = useState({
        url: '',
        titulo: '',
        descripcion: '',
        portada: null,
        categoria_id: '',
        portadaPreview: null
    });

    useEffect(() => {
        if (isOpen) {
            // Inicializar categoria_id con defaultFolderId si está disponible
            setFormData(prev => ({
                ...prev,
                categoria_id: defaultFolderId || ''
            }));
            loadTags();
            loadCategories();
        } else {
            // Limpiar toast al cerrar el modal
            if (scrapingToastId) {
                toast.removeToast?.(scrapingToastId);
                setScrapingToastId(null);
            }
        }
    }, [isOpen, defaultFolderId]);

    // Web scraping
    useEffect(() => {
        const debounceTimer = setTimeout(() => {
            if (formData.url.trim() && formData.url.startsWith('http')) {
                performScrape(formData.url.trim());
            }
        }, 1000); // Espera 1 segundo después de que el usuario deje de escribir

        return () => clearTimeout(debounceTimer);
    }, [formData.url]);

    // Mostrar bloqueo inmediatamente al detectar URL
    useEffect(() => {
        const hasUrl = formData.url.trim() && formData.url.startsWith('http');

        if (hasUrl && !scrapingToastId) {
            // Mostrar toast inmediatamente cuando hay URL
            const toastId = toast.info('Buscando metadatos…', 3000);
            setScrapingToastId(toastId);
        } else if (!hasUrl && scrapingToastId) {
            // Ocultar toast si se borra la URL
            toast.removeToast?.(scrapingToastId);
            setScrapingToastId(null);
        }
    }, [formData.url]);

    // Extender duración del toast mientras hay scraping en progreso
    useEffect(() => {
        if (scrapingUrl && scrapingToastId) {
            // Si hay scraping activo y hay un toast, mantener el toast visible
            // No hacer nada, el toast ya debería estar visible
        } else if (!scrapingUrl && scrapingToastId && (formData.url.trim() && formData.url.startsWith('http'))) {
            // Scraping completado, mantener el toast 3 segundos más
            const timerId = setTimeout(() => {
                toast.removeToast?.(scrapingToastId);
                setScrapingToastId(null);
            }, 3000);
            return () => clearTimeout(timerId);
        }
    }, [scrapingUrl]);

    const performScrape = async (url) => {
        try {
            setScrapingUrl(url);
            const result = await bookmarksService.scrapeUrl(url);

            if (result.success) {
                // Actualizar título y descripción
                setFormData(prev => ({
                    ...prev,
                    titulo: result.titulo,
                    descripcion: result.descripcion
                }));

                // Guardar datos de GitHub si existen
                if (result.gitHubData) {
                    console.log('[Frontend] Datos de GitHub encontrados:', result.gitHubData);
                    setGitHubData(result.gitHubData);
                } else {
                    setGitHubData(null);
                }

                // Aplicar tags automáticos si los hay
                if (result.autoTags && result.autoTags.length > 0) {
                    console.log('[Frontend] Tags detectados automáticamente:', result.autoTags);
                    setSelectedTagIds(result.autoTags);
                    // Mostrar notificación de tags detectados (solo si tags ya está cargado)
                    if (tags && tags.length > 0) {
                        const tagsNombres = tags
                            .filter(t => result.autoTags.includes(t.id))
                            .map(t => t.nombre)
                            .join(', ');
                        if (tagsNombres) {
                            console.log(`[Frontend] Tags aplicados: ${tagsNombres}`);
                        }
                    }
                } else {
                    console.log('[Frontend] No se detectaron tags automáticamente');
                }
            }
        } catch (err) {
            console.error('Error en scraping:', err);
        } finally {
            setScrapingUrl(null);
        }
    };

    const loadTags = async () => {
        try {
            const data = await tagsService.getAll();
            // Asegurar que los IDs de los tags sean números
            const tagsWithNumericIds = (data || []).map(tag => ({
                ...tag,
                id: parseInt(tag.id, 10)
            }));
            setTags(tagsWithNumericIds);
        } catch (err) {
            console.error('Error cargando tags:', err);
        }
    };

    const loadCategories = async () => {
        try {
            const data = await categoriesService.getAll();
            setCategories(data || []);
        } catch (err) {
            console.error('Error cargando carpetas:', err);
        }
    };

    // Función para aplanar las carpetas y mostrar todas incluyendo subcarpetas
    const flattenCategories = (cats, prefix = '') => {
        let result = [];
        (cats || []).forEach(cat => {
            result.push({
                ...cat,
                displayName: prefix + cat.nombre
            });
            if (cat.children && cat.children.length > 0) {
                result = result.concat(flattenCategories(cat.children, prefix + '  '));
            }
        });
        return result;
    };

    if (!isOpen) return null;

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleClose = () => {
        // Limpiar formulario antes de cerrar
        setFormData({
            url: '',
            titulo: '',
            descripcion: '',
            portada: null,
            categoria_id: defaultFolderId || '',
            portadaPreview: null
        });
        setSelectedTagIds([]);
        setGitHubData(null);
        setError(null);

        // Limpiar toast
        if (scrapingToastId) {
            toast.removeToast?.(scrapingToastId);
            setScrapingToastId(null);
        }

        // Cerrar modal
        onClose();
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            const preview = URL.createObjectURL(file);
            setFormData({ ...formData, portada: file, portadaPreview: preview });
        }
    };

    const handleToggleTag = (tagId) => {
        setSelectedTagIds((prevIds) => {
            if (prevIds.includes(tagId)) {
                return prevIds.filter(id => id !== tagId);
            } else {
                return [...prevIds, tagId];
            }
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!formData.url.trim() || !formData.titulo.trim()) {
            toast.error('URL y nombre son requeridos');
            return;
        }

        try {
            setLoading(true);
            setError(null);

            // Crear FormData para enviar con imagen
            const submitData = new FormData();
            submitData.append('titulo', formData.titulo.trim());
            submitData.append('url', formData.url.trim());
            submitData.append('descripcion', formData.descripcion.trim() || '');

            if (formData.portada) {
                submitData.append('portada', formData.portada);
            }

            if (formData.categoria_id) {
                submitData.append('categoria_id', formData.categoria_id);
            }

            // Agregar tags
            if (selectedTagIds.length > 0) {
                submitData.append('tags', JSON.stringify(selectedTagIds));
            }

            // Agregar datos de GitHub si existen
            if (gitHubData) {
                submitData.append('github_stars', gitHubData.stars || 0);
                submitData.append('github_forks', gitHubData.forks || 0);
                submitData.append('github_watchers', gitHubData.watchers || 0);
                if (gitHubData.languages && gitHubData.languages.length > 0) {
                    submitData.append('github_languages', JSON.stringify(gitHubData.languages));
                }
            }

            const newBookmark = await bookmarksService.create(submitData);

            console.log('Bookmark creado:', newBookmark);

            if (!newBookmark || !newBookmark.id) {
                throw new Error('No se recibió un marcador válido del servidor');
            }

            // Resetear formulario
            setFormData({
                url: '',
                titulo: '',
                descripcion: '',
                portada: null,
                categoria_id: '',
                portadaPreview: null
            });
            setSelectedTagIds([]);
            setGitHubData(null);

            // Disparar evento global para notificar que se creó un marcador
            window.dispatchEvent(new CustomEvent('bookmarkCreated', { detail: newBookmark }));

            // Notificar al padre
            if (onBookmarkCreated) {
                onBookmarkCreated(newBookmark);
            }

            toast.success('Marcador creado correctamente');
            onClose();
        } catch (err) {
            console.error('Error creando marcador:', err);
            toast.error(err.message || 'Error al crear el marcador');
        } finally {
            setLoading(false);
        }
    };

    const selectedTags = tags.filter(tag => selectedTagIds.includes(tag.id));

    return (
        <div className="modal-overlay" onMouseDown={handleClose}>
            <section className="modal-content modal-content--large" onMouseDown={(e) => e.stopPropagation()} aria-labelledby="bookmark-modal-title">

                <h2 id="bookmark-modal-title" className="visually-hidden">Crear nuevo marcador</h2>

                {error && (
                    <div style={{ color: 'red', backgroundColor: '#ffebee', padding: '10px', marginBottom: '10px', borderRadius: '4px' }}>
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit} className="bookmark-form">

                    <div className="modal__field">
                        <label htmlFor="bookmark-url">URL</label>
                        <input 
                            id="bookmark-url" 
                            type="url" 
                            name="url"
                            placeholder="Introduzca la URL del sitio web" 
                            className="modal__input" 
                            value={formData.url}
                            onChange={handleInputChange}
                            required 
                        />
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-name">Nombre</label>
                        <input 
                            id="bookmark-name" 
                            type="text" 
                            name="titulo"
                            placeholder="Introduzca el nombre del sitio web" 
                            className="modal__input" 
                            value={formData.titulo}
                            onChange={handleInputChange}
                            disabled={scrapingUrl !== null}
                            required 
                        />
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-desc">Descripcion</label>
                        <textarea 
                            id="bookmark-desc" 
                            name="descripcion"
                            placeholder="Introduzca la descripcion del sitio web" 
                            className="modal__input modal__textarea"
                            value={formData.descripcion}
                            onChange={handleInputChange}
                            disabled={scrapingUrl !== null}
                        ></textarea>
                    </div>


                    <div className="modal__field modal__field--file">
                        <div className="modal__file-info">
                            <label>Portada</label>
                            <span className="modal__help-text">Eliga una imagen de portada (archivos permitidos: .png, .jpg, .svg)</span>
                        </div>
                        <label className="modal__upload-btn">
                            Subir imagen
                            <input 
                                type="file" 
                                accept=".png, .jpg, .jpeg, .svg" 
                                className="visually-hidden"
                                onChange={handleFileChange}
                            />
                        </label>
                        {formData.portadaPreview && (
                            <div style={{ marginTop: '10px' }}>
                                <img src={formData.portadaPreview} alt="Preview" style={{ maxWidth: '100px', maxHeight: '100px' }} />
                            </div>
                        )}
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-folder">Carpeta</label>
                        <div className="modal__folder-row">
                            <select 
                                id="bookmark-folder" 
                                name="categoria_id"
                                className="modal__select modal__select--small"
                                value={formData.categoria_id}
                                onChange={handleInputChange}
                            >
                                <option value="">Sección general</option>
                                {flattenCategories(categories).map(cat => (
                                    <option key={cat.id} value={cat.id}>
                                        {cat.displayName}
                                    </option>
                                ))}
                            </select>
                            <span className="modal__help-text">Por defecto, el marcador se<br/>guardara en la seccion general</span>
                        </div>
                    </div>

                    <div className="modal__field modal__field--inline">
                         <label>Tags: 
                             {selectedTagIds.length > 0 && (
                                 <span style={{ fontSize: '12px', color: '#666', marginLeft: '8px' }}>
                                     ({selectedTagIds.length} seleccionado{selectedTagIds.length !== 1 ? 's' : ''})
                                 </span>
                             )}
                         </label>

                         <div className="modal__selected-tags">
                             {selectedTags.length > 0 ? (
                                 selectedTags.map(tag => (
                                     <TagBadge 
                                         key={tag.id} 
                                         texto={tag.nombre} 
                                         colorHex={tag.color} 
                                         isSelected={false} 
                                     />
                                 ))
                             ) : (
                                 <span style={{ fontSize: '13px', color: '#999' }}>Sin tags seleccionados</span>
                             )}
                         </div>

                        <button 
                            type="button" 
                            className="modal__add-tag-btn" 
                            onClick={() => setIsPopoverOpen(true)}
                        >
                            +
                        </button>

                        <TagPopover
                            isOpen={isPopoverOpen}
                            onClose={() => setIsPopoverOpen(false)}
                            availableTags={tags}
                            selectedTags={selectedTagIds}
                            onToggleTag={handleToggleTag}
                        />
                    </div>

                    <div className="modal__actions">
                        <button 
                            type="submit" 
                            className="modal__submit-btn"
                            disabled={loading}
                        >
                            {loading ? 'Creando...' : 'Crear'}
                        </button>
                    </div>

                </form>
            </section>
        </div>
    );
}

export default CreateBookmarkModal;

import React, { useState, useEffect } from 'react';
import TagBadge from './TagBadge';
import TagPopover from './TagPopover';
import { bookmarksService } from '../services/bookmarksService';
import { tagsService } from '../services/tagsService';
import { categoriesService } from '../services/categoriesService';
import { useToast } from '../hooks/useToast';
import './CreateBookmarkModal.css';

function CreateBookmarkModal({ isOpen, onClose, onBookmarkCreated, defaultFolderId }) {
    const toast = useToast();
    const [isPopoverOpen, setIsPopoverOpen] = useState(false);
    const [selectedTagIds, setSelectedTagIds] = useState([]);
    const [tags, setTags] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [scrapingUrl, setScrapingUrl] = useState(null);
    const [scrapingToastId, setScrapingToastId] = useState(null);
    const [gitHubData, setGitHubData] = useState(null); // Almacena datos de GitHub
    
    const [formData, setFormData] = useState({
        url: '',
        titulo: '',
        descripcion: '',
        portada: null,
        categoria_id: '',
        portadaPreview: null
    });

    useEffect(() => {
        if (isOpen) {
            // Inicializar categoria_id con defaultFolderId si está disponible
            setFormData(prev => ({
                ...prev,
                categoria_id: defaultFolderId || ''
            }));
            loadTags();
            loadCategories();
        } else {
            // Limpiar toast al cerrar el modal
            if (scrapingToastId) {
                toast.removeToast?.(scrapingToastId);
                setScrapingToastId(null);
            }
        }
    }, [isOpen, defaultFolderId]);

    // Web scraping
    useEffect(() => {
        const debounceTimer = setTimeout(() => {
            if (formData.url.trim() && formData.url.startsWith('http')) {
                performScrape(formData.url.trim());
            }
        }, 1000); // Espera 1 segundo después de que el usuario deje de escribir

        return () => clearTimeout(debounceTimer);
    }, [formData.url]);

    // Mostrar bloqueo inmediatamente al detectar URL
    useEffect(() => {
        const hasUrl = formData.url.trim() && formData.url.startsWith('http');
        
        if (hasUrl && !scrapingToastId) {
            // Mostrar toast inmediatamente cuando hay URL
            const toastId = toast.info('Buscando metadatos…', 3000);
            setScrapingToastId(toastId);
        } else if (!hasUrl && scrapingToastId) {
            // Ocultar toast si se borra la URL
            toast.removeToast?.(scrapingToastId);
            setScrapingToastId(null);
        }
    }, [formData.url]);

    // Extender duración del toast mientras hay scraping en progreso
    useEffect(() => {
        if (scrapingUrl && scrapingToastId) {
            // Si hay scraping activo y hay un toast, mantener el toast visible
            // No hacer nada, el toast ya debería estar visible
        } else if (!scrapingUrl && scrapingToastId && (formData.url.trim() && formData.url.startsWith('http'))) {
            // Scraping completado, mantener el toast 3 segundos más
            const timerId = setTimeout(() => {
                toast.removeToast?.(scrapingToastId);
                setScrapingToastId(null);
            }, 3000);
            return () => clearTimeout(timerId);
        }
    }, [scrapingUrl]);

    const performScrape = async (url) => {
        try {
            setScrapingUrl(url);
            const result = await bookmarksService.scrapeUrl(url);
            
            if (result.success) {
                // Actualizar título y descripción
                setFormData(prev => ({
                    ...prev,
                    titulo: result.titulo,
                    descripcion: result.descripcion
                }));

                // Guardar datos de GitHub si existen
                if (result.gitHubData) {
                    console.log('[Frontend] Datos de GitHub encontrados:', result.gitHubData);
                    setGitHubData(result.gitHubData);
                } else {
                    setGitHubData(null);
                }

                // Aplicar tags automáticos si los hay
                if (result.autoTags && result.autoTags.length > 0) {
                    console.log('[Frontend] Tags detectados automáticamente:', result.autoTags);
                    setSelectedTagIds(result.autoTags);
                    // Mostrar notificación de tags detectados (solo si tags ya está cargado)
                    if (tags && tags.length > 0) {
                        const tagsNombres = tags
                            .filter(t => result.autoTags.includes(t.id))
                            .map(t => t.nombre)
                            .join(', ');
                        if (tagsNombres) {
                            console.log(`[Frontend] Tags aplicados: ${tagsNombres}`);
                        }
                    }
                } else {
                    console.log('[Frontend] No se detectaron tags automáticamente');
                }
            }
        } catch (err) {
            console.error('Error en scraping:', err);
        } finally {
            setScrapingUrl(null);
        }
    };

    const loadTags = async () => {
        try {
            const data = await tagsService.getAll();
            // Asegurar que los IDs de los tags sean números
            const tagsWithNumericIds = (data || []).map(tag => ({
                ...tag,
                id: parseInt(tag.id, 10)
            }));
            setTags(tagsWithNumericIds);
        } catch (err) {
            console.error('Error cargando tags:', err);
        }
    };

    const loadCategories = async () => {
        try {
            const data = await categoriesService.getAll();
            setCategories(data || []);
        } catch (err) {
            console.error('Error cargando carpetas:', err);
        }
    };

    // Función para aplanar las carpetas y mostrar todas incluyendo subcarpetas
    const flattenCategories = (cats, prefix = '') => {
        let result = [];
        (cats || []).forEach(cat => {
            result.push({
                ...cat,
                displayName: prefix + cat.nombre
            });
            if (cat.children && cat.children.length > 0) {
                result = result.concat(flattenCategories(cat.children, prefix + '  '));
            }
        });
        return result;
    };

    if (!isOpen) return null;

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleClose = () => {
        // Limpiar formulario antes de cerrar
        setFormData({
            url: '',
            titulo: '',
            descripcion: '',
            portada: null,
            categoria_id: defaultFolderId || '',
            portadaPreview: null
        });
        setSelectedTagIds([]);
        setGitHubData(null);
        setError(null);
        
        // Limpiar toast
        if (scrapingToastId) {
            toast.removeToast?.(scrapingToastId);
            setScrapingToastId(null);
        }
        
        // Cerrar modal
        onClose();
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            const preview = URL.createObjectURL(file);
            setFormData({ ...formData, portada: file, portadaPreview: preview });
        }
    };

    const handleToggleTag = (tagId) => {
        setSelectedTagIds((prevIds) => {
            if (prevIds.includes(tagId)) {
                return prevIds.filter(id => id !== tagId);
            } else {
                return [...prevIds, tagId];
            }
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!formData.url.trim() || !formData.titulo.trim()) {
            toast.error('URL y nombre son requeridos');
            return;
        }

        try {
            setLoading(true);
            setError(null);

            // Crear FormData para enviar con imagen
            const submitData = new FormData();
            submitData.append('titulo', formData.titulo.trim());
            submitData.append('url', formData.url.trim());
            submitData.append('descripcion', formData.descripcion.trim() || '');
            
            if (formData.portada) {
                submitData.append('portada', formData.portada);
            }
            
            if (formData.categoria_id) {
                submitData.append('categoria_id', formData.categoria_id);
            }

            // Agregar tags
            if (selectedTagIds.length > 0) {
                submitData.append('tag_ids', JSON.stringify(selectedTagIds));
            }

            // Agregar datos de GitHub si existen
            if (gitHubData) {
                submitData.append('github_stars', gitHubData.stars || 0);
                submitData.append('github_forks', gitHubData.forks || 0);
                submitData.append('github_watchers', gitHubData.watchers || 0);
                if (gitHubData.languages && gitHubData.languages.length > 0) {
                    submitData.append('github_languages', JSON.stringify(gitHubData.languages));
                }
            }

            const newBookmark = await bookmarksService.create(submitData);
            
            console.log('Bookmark creado:', newBookmark);
            
            if (!newBookmark || !newBookmark.id) {
                throw new Error('No se recibió un marcador válido del servidor');
            }
            
            // Resetear formulario
            setFormData({
                url: '',
                titulo: '',
                descripcion: '',
                portada: null,
                categoria_id: '',
                portadaPreview: null
            });
            setSelectedTagIds([]);
            setGitHubData(null);
            
            // Disparar evento global para notificar que se creó un marcador
            window.dispatchEvent(new CustomEvent('bookmarkCreated', { detail: newBookmark }));
            
            // Notificar al padre
            if (onBookmarkCreated) {
                onBookmarkCreated(newBookmark);
            }
            
            toast.success('Marcador creado correctamente');
            onClose();
        } catch (err) {
            console.error('Error creando marcador:', err);
            toast.error(err.message || 'Error al crear el marcador');
        } finally {
            setLoading(false);
        }
    };

    const selectedTags = tags.filter(tag => selectedTagIds.includes(tag.id));

    return (
        <div className="modal-overlay" onMouseDown={handleClose}>
            <section className="modal-content modal-content--large" onMouseDown={(e) => e.stopPropagation()} aria-labelledby="bookmark-modal-title">

                <h2 id="bookmark-modal-title" className="visually-hidden">Crear nuevo marcador</h2>

                {error && (
                    <div style={{ color: 'red', backgroundColor: '#ffebee', padding: '10px', marginBottom: '10px', borderRadius: '4px' }}>
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit} className="bookmark-form">

                    <div className="modal__field">
                        <label htmlFor="bookmark-url">URL</label>
                        <input 
                            id="bookmark-url" 
                            type="url" 
                            name="url"
                            placeholder="Introduzca la URL del sitio web" 
                            className="modal__input" 
                            value={formData.url}
                            onChange={handleInputChange}
                            required 
                        />
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-name">Nombre</label>
                        <input 
                            id="bookmark-name" 
                            type="text" 
                            name="titulo"
                            placeholder="Introduzca el nombre del sitio web" 
                            className="modal__input" 
                            value={formData.titulo}
                            onChange={handleInputChange}
                            disabled={scrapingUrl !== null}
                            required 
                        />
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-desc">Descripcion</label>
                        <textarea 
                            id="bookmark-desc" 
                            name="descripcion"
                            placeholder="Introduzca la descripcion del sitio web" 
                            className="modal__input modal__textarea"
                            value={formData.descripcion}
                            onChange={handleInputChange}
                            disabled={scrapingUrl !== null}
                        ></textarea>
                    </div>


                    <div className="modal__field modal__field--file">
                        <div className="modal__file-info">
                            <label>Portada</label>
                            <span className="modal__help-text">Eliga una imagen de portada (archivos permitidos: .png, .jpg, .svg)</span>
                        </div>
                        <label className="modal__upload-btn">
                            Subir imagen
                            <input 
                                type="file" 
                                accept=".png, .jpg, .jpeg, .svg" 
                                className="visually-hidden"
                                onChange={handleFileChange}
                            />
                        </label>
                        {formData.portadaPreview && (
                            <div style={{ marginTop: '10px' }}>
                                <img src={formData.portadaPreview} alt="Preview" style={{ maxWidth: '100px', maxHeight: '100px' }} />
                            </div>
                        )}
                    </div>

                    <div className="modal__field">
                        <label htmlFor="bookmark-folder">Carpeta</label>
                        <div className="modal__folder-row">
                            <select 
                                id="bookmark-folder" 
                                name="categoria_id"
                                className="modal__select modal__select--small"
                                value={formData.categoria_id}
                                onChange={handleInputChange}
                            >
                                <option value="">Sección general</option>
                                {flattenCategories(categories).map(cat => (
                                    <option key={cat.id} value={cat.id}>
                                        {cat.displayName}
                                    </option>
                                ))}
                            </select>
                            <span className="modal__help-text">Por defecto, el marcador se<br/>guardara en la seccion general</span>
                        </div>
                    </div>

                    <div className="modal__field modal__field--inline">
                         <label>Tags: 
                             {selectedTagIds.length > 0 && (
                                 <span style={{ fontSize: '12px', color: '#666', marginLeft: '8px' }}>
                                     ({selectedTagIds.length} seleccionado{selectedTagIds.length !== 1 ? 's' : ''})
                                 </span>
                             )}
                         </label>

                         <div className="modal__selected-tags">
                             {selectedTags.length > 0 ? (
                                 selectedTags.map(tag => (
                                     <TagBadge 
                                         key={tag.id} 
                                         texto={tag.nombre} 
                                         colorHex={tag.color} 
                                         isSelected={false} 
                                     />
                                 ))
                             ) : (
                                 <span style={{ fontSize: '13px', color: '#999' }}>Sin tags seleccionados</span>
                             )}
                         </div>

                        <button 
                            type="button" 
                            className="modal__add-tag-btn" 
                            onClick={() => setIsPopoverOpen(true)}
                        >
                            +
                        </button>

                        <TagPopover
                            isOpen={isPopoverOpen}
                            onClose={() => setIsPopoverOpen(false)}
                            availableTags={tags}
                            selectedTags={selectedTagIds}
                            onToggleTag={handleToggleTag}
                        />
                    </div>

                    <div className="modal__actions">
                        <button 
                            type="submit" 
                            className="modal__submit-btn"
                            disabled={loading}
                        >
                            {loading ? 'Creando...' : 'Crear'}
                        </button>
                    </div>

                </form>
            </section>
        </div>
    );
}

export default CreateBookmarkModal;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import ManageBookmark from './ManageBookmark';
import QuickActionsPanel from './QuickActionsPanel';
import DeleteBookmarkModal from './DeleteBookmarkModal';
import SearchResultsPanel from './SearchResultsPanel';
import { bookmarksService } from '../services/bookmarksService';
import { categoriesService } from '../services/categoriesService';
import { tagsService } from '../services/tagsService';
import { useToast } from '../hooks/useToast';
import './ManageBookmarksContent.css';

function ManageBookmarksContent() {
    const [searchParams] = useSearchParams();
    const navigate = useNavigate();
    const toast = useToast();
    const [bookmarks, setBookmarks] = useState([]);
    const [editedBookmark, setEditedBookmark] = useState(null);
    const [originalData, setOriginalData] = useState(null);
    const [unsavedChangesToastId, setUnsavedChangesToastId] = useState(null);
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [folders, setFolders] = useState([]);
    const [allTags, setAllTags] = useState([]);
    const [updating, setUpdating] = useState(false);

    // Cargar bookmarks, carpetas y tags al montar el componente
    useEffect(() => {
        loadBookmarks();
        loadFolders();
        loadTags();

        // Limpiar toast al desmontar
        return () => {
            if (unsavedChangesToastId) {
                toast.removeToast?.(unsavedChangesToastId);
            }
        };
    }, []);

    // Seleccionar el bookmark según el parámetro de URL o el primero si no hay
    useEffect(() => {
        const bookmarkIdFromUrl = searchParams.get('id');

        if (bookmarkIdFromUrl) {
            // Si hay un ID en la URL, cargar ese marcador específico
            loadSpecificBookmark(parseInt(bookmarkIdFromUrl, 10));
        } else if (bookmarks.length > 0 && !editedBookmark) {
            // Si no hay ID en URL, seleccionar el primer marcador de la lista
            setEditedBookmark(bookmarks[0]);
            setOriginalData(JSON.parse(JSON.stringify(bookmarks[0])));
        }
    }, [bookmarks, searchParams]);

    // Detectar cambios en el bookmark editado
    useEffect(() => {
        if (!editedBookmark || !originalData) {
            return;
        }

        // Convertir ambos a JSON para comparación exacta
        try {
            const editedStr = JSON.stringify({
                titulo: editedBookmark.titulo,
                url: editedBookmark.url,
                descripcion: editedBookmark.descripcion,
                categoria_id: editedBookmark.categoria_id,
                tags: (editedBookmark.tags || []).map(t => t.id).sort(),
                portada: editedBookmark.portada,
                id: editedBookmark.id
            });

            const originalStr = JSON.stringify({
                titulo: originalData.titulo,
                url: originalData.url,
                descripcion: originalData.descripcion,
                categoria_id: originalData.categoria_id,
                tags: (originalData.tags || []).map(t => t.id).sort(),
                portada: originalData.portada,
                id: originalData.id
            });

            const hasChanges = editedStr !== originalStr;

            if (hasChanges) {
                // Si hay cambios y no hay toast, mostrar
                if (!unsavedChangesToastId) {
                    const toastId = toast.warning('Cambios sin guardar', 3000);
                    setUnsavedChangesToastId(toastId);
                }
            } else {
                // Si no hay cambios y hay un toast, ocultarlo
                if (unsavedChangesToastId) {
                    toast.removeToast?.(unsavedChangesToastId);
                    setUnsavedChangesToastId(null);
                }
            }
        } catch (err) {
            console.error('Error al comparar cambios:', err);
        }
    }, [editedBookmark, originalData]);

    const loadBookmarks = async () => {
        try {
            setLoading(true);
            const data = await bookmarksService.getAll({ all: true });
            setBookmarks(data || []);
            if (error) setError(null);
        } catch (err) {
            console.error('Error cargando marcadores:', err);
            setError(err.message);
            setBookmarks([]);
        } finally {
            setLoading(false);
        }
    };

    const loadSpecificBookmark = async (bookmarkId) => {
        try {
            // Cargar el marcador específico por ID
            const bookmark = await bookmarksService.getById(bookmarkId);
            if (bookmark) {
                setEditedBookmark(bookmark);
                setOriginalData(JSON.parse(JSON.stringify(bookmark)));
            } else {
                // Si no existe, usar el primero de la lista
                if (bookmarks.length > 0) {
                    setEditedBookmark(bookmarks[0]);
                    setOriginalData(JSON.parse(JSON.stringify(bookmarks[0])));
                }
            }
        } catch (err) {
            console.error('Error cargando marcador específico:', err);
            // Fallback: usar el primero de la lista
            if (bookmarks.length > 0) {
                setEditedBookmark(bookmarks[0]);
                setOriginalData(JSON.parse(JSON.stringify(bookmarks[0])));
            }
        }
    };

    const loadFolders = async () => {
        try {
            const data = await categoriesService.getAll();
            setFolders(data || []);
        } catch (err) {
            console.error('Error cargando carpetas:', err);
            setFolders([]);
        }
    };

    const loadTags = async () => {
        try {
            const data = await tagsService.getAll();
            // Asegurar que los IDs de los tags sean números
            const tagsWithNumericIds = (data || []).map(tag => ({
                ...tag,
                id: parseInt(tag.id, 10)
            }));
            setAllTags(tagsWithNumericIds);
        } catch (err) {
            console.error('Error cargando tags:', err);
            setAllTags([]);
        }
    };

    const handleInputChange = (field, value) => {
        setEditedBookmark({ ...editedBookmark, [field]: value });
    };

    const handleFileChange = (file) => {
        setEditedBookmark({ ...editedBookmark, portadaFile: file });
    };

    const handleToggleTag = (tagId) => {
        const currentTags = editedBookmark.tags || [];
        const isAlreadySelected = currentTags.some(t => t.id === tagId);

        let newTags;
        if (isAlreadySelected) {
            newTags = currentTags.filter(t => t.id !== tagId);
        } else {
            const tagToAdd = allTags.find(t => t.id === tagId);
            if (tagToAdd) {
                newTags = [...currentTags, tagToAdd];
            } else {
                newTags = currentTags;
            }
        }

        setEditedBookmark({ ...editedBookmark, tags: newTags });
    };

    const handleUpdate = async () => {
        try {
            if (!editedBookmark.titulo || editedBookmark.titulo.trim() === '') {
                toast.error('El nombre del marcador no puede estar vacío');
                return;
            }

            setUpdating(true);

            // Preparar datos para actualizar
            const submitData = new FormData();
            submitData.append('titulo', editedBookmark.titulo.trim());
            submitData.append('url', editedBookmark.url || '');
            submitData.append('descripcion', editedBookmark.descripcion || '');

            if (editedBookmark.portadaFile) {
                submitData.append('portada', editedBookmark.portadaFile);
            }

            // Siempre enviar categoria_id, incluso si es vacío/null (para sección general)
            submitData.append('categoria_id', editedBookmark.categoria_id || '');

            // Agregar tags
            const tagIds = editedBookmark.tags?.map(t => t.id) || [];
            if (tagIds.length > 0) {
                submitData.append('tags', JSON.stringify(tagIds));
            }

            const updatedBookmark = await bookmarksService.update(editedBookmark.id, submitData);

            // Actualizar la lista con los datos del servidor
            const updatedBookmarks = bookmarks.map(b => 
                b.id === editedBookmark.id ? updatedBookmark : b
            );
            setBookmarks(updatedBookmarks);

            // Sincronizar: hacer copia profunda sin portadaFile para que sean idénticos
            const cleanUpdateBookmark = JSON.parse(JSON.stringify(updatedBookmark));
            setEditedBookmark(cleanUpdateBookmark);

            // Limpiar toast de cambios sin guardar
            if (unsavedChangesToastId) {
                toast.removeToast?.(unsavedChangesToastId);
                setUnsavedChangesToastId(null);
            }

            // Actualizar datos originales con la misma copia
            setOriginalData(JSON.parse(JSON.stringify(cleanUpdateBookmark)));

            toast.success('Marcador actualizado correctamente');
        } catch (err) {
            console.error('Error actualizando marcador:', err);
            toast.error(`Error al actualizar: ${err.message}`);
        } finally {
            setUpdating(false);
        }
    };

    const handleVisitWebpage = () => {
        let finalUrl = editedBookmark.url;
        if (!finalUrl.startsWith('http://') && !finalUrl.startsWith('https://')) {
            finalUrl = 'https://' + finalUrl;
        }
        window.open(finalUrl, '_blank', 'noopener,noreferrer');
    };

    const handleDelete = async () => {
        try {
            await bookmarksService.delete(editedBookmark.id);

            setIsDeleteModalOpen(false);
            toast.success('Marcador eliminado correctamente');

            // Navegar a HomePage después de eliminar
            navigate('/');
        } catch (err) {
            console.error('Error eliminando marcador:', err);
            toast.error(`Error al eliminar: ${err.message}`);
        }
    };

    const handleRemovePortada = async () => {
        try {
            setUpdating(true);

            // Limpiar inmediatamente en el frontend
            const cleanedBookmark = {
                ...editedBookmark,
                portada: null
            };
            setEditedBookmark(cleanedBookmark);

            // Preparar datos para actualizar sin portada
            const submitData = new FormData();
            submitData.append('titulo', editedBookmark.titulo.trim());
            submitData.append('url', editedBookmark.url || '');
            submitData.append('descripcion', editedBookmark.descripcion || '');
            submitData.append('portada', ''); // Vaciar portada

            if (editedBookmark.categoria_id) {
                submitData.append('categoria_id', editedBookmark.categoria_id);
            }

            // Agregar tags
            const tagIds = editedBookmark.tags?.map(t => t.id) || [];
            if (tagIds.length > 0) {
                submitData.append('tags', JSON.stringify(tagIds));
            }

            const updatedBookmark = await bookmarksService.update(editedBookmark.id, submitData);

            // Actualizar la lista con los datos del servidor
            const updatedBookmarks = bookmarks.map(b => 
                b.id === editedBookmark.id ? updatedBookmark : b
            );
            setBookmarks(updatedBookmarks);

            // Sincronizar: hacer copia profunda para que sean idénticos
            const cleanUpdateBookmark = JSON.parse(JSON.stringify(updatedBookmark));
            setEditedBookmark(cleanUpdateBookmark);

            // Limpiar toast de cambios sin guardar
            if (unsavedChangesToastId) {
                toast.removeToast?.(unsavedChangesToastId);
                setUnsavedChangesToastId(null);
            }

            // Actualizar datos originales con la misma copia
            setOriginalData(JSON.parse(JSON.stringify(cleanUpdateBookmark)));

            toast.success('Portada eliminada correctamente');
        } catch (err) {
            console.error('Error eliminando portada:', err);
            toast.error(`Error al eliminar portada: ${err.message}`);
            // Revertir el cambio en caso de error
            loadBookmarks();
        } finally {
            setUpdating(false);
        }
    };

    if (loading) {
        return (
            <div className="manage-page-layout">
                <div className="manage-header">
                    <h2>Gestiona tus marcadores</h2>
                </div>
                <p style={{ padding: '20px' }}>Cargando marcadores...</p>
            </div>
        );
    }

    if (bookmarks.length === 0) {
        return (
            <div className="manage-page-layout">
                <div className="manage-header">
                    <h2>Gestiona tus marcadores</h2>
                </div>
                <p style={{ padding: '20px' }}>No hay marcadores disponibles</p>
            </div>
        );
    }

    return (
        <div className="manage-page-layout">
            <div className="manage-header">
                <h2>Gestiona tu marcador</h2>
            </div>

            {error && (
                <div style={{ color: 'red', padding: '20px', backgroundColor: '#ffebee', margin: '10px' }}>
                    Error: {error}
                </div>
            )}

            <SearchResultsPanel />

            {editedBookmark && (
                <div className="manage-content manage-content--2-cols">
                    <ManageBookmark
                        bookmark={editedBookmark}
                        onChange={handleInputChange}
                        onFileChange={handleFileChange}
                        availableFolders={folders}
                        systemTags={allTags}
                        onToggleTag={handleToggleTag}
                        onRemovePortada={handleRemovePortada}
                    />

                    <QuickActionsPanel
                        viewButtonText="Visitar página web"
                        onUpdate={handleUpdate}
                        onView={handleVisitWebpage}
                        onDelete={() => setIsDeleteModalOpen(true)}
                        isLoading={updating}
                    />
                </div>
            )}

            <DeleteBookmarkModal
                isOpen={isDeleteModalOpen}
                onClose={() => setIsDeleteModalOpen(false)}
                bookmarkName={editedBookmark?.titulo || 'sin nombre'}
                onDelete={handleDelete}
            />
        </div>
    );
}

export default ManageBookmarksContent;

